#!/usr/bin/env python3
import datetime,hashlib,json,shutil,subprocess,tarfile
from pathlib import Path
O=Path(__file__).resolve().parent;R=O.parents[1];s=json.loads((O/'state.json').read_text());S=Path(s['scratch']);v=json.loads((O/'source-verification.json').read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def digest(x):return hashlib.sha256(json.dumps(x,sort_keys=True,separators=(',',':')).encode()).hexdigest()
def save(n,x):(O/n).write_text(json.dumps(x,indent=2)+'\n')
assert all(sha(S/p)==h for p,h in v['correctedSource'].items())
assert all(sha(R/p)==h for p,h in v['liveHosted'].items())
for name,expected in v['packets'].items():
 P=R/'verification'/name;x=json.loads((P/'receipt.json').read_text());assert sha(P/'receipt.json')==expected['receiptSHA256'];assert all(sha(P/n)==h for n,h in x['bindings'].items())
p=subprocess.run(['python3',str(O/'assess_evidence.py')],cwd=R,capture_output=True);(O/'evidence-assessment.log').write_bytes(p.stdout+p.stderr);assert p.returncode==0
fresh={str(p.relative_to(S)):sha(p) for p in (S/'hosted').rglob('*') if p.is_file() and not {'deps','_build','__pycache__','cover'}.intersection(p.relative_to(S).parts) and p.name!='erl_crash.dump'}
fresh.update({p:sha(S/p) for p in v['correctedSource'] if p.startswith('services/')})
assert len(fresh)==72
initial=dict(fresh);initial['hosted/test/mixer_hosted/identity/review_endpoint_boundary_test.exs']=sha(O/'review_endpoint_boundary_test-attempt1.exs')
save('review-source-manifest.json',{'finalFiles':fresh,'finalDigest':digest(fresh),'initialTestAttemptFiles':initial,'initialDigest':digest(initial),'correctedCandidateDigest':v['correctedSourceDigest'],'dependencyDigest':v['dependencyDigest'],'note':'Only three packet-local reviewer test files augment the 69-file candidate. Initial and final differ solely in the reviewer dot-separator expectation.'})
with tarfile.open(O/'review-source.tar.gz','w:gz') as t:
 for n in sorted(fresh):t.add(S/n,arcname=n,recursive=False)
for c in s['commands']:
 if c['label'] in ['old-adversarial','old-minimal','correction-focused','independent-boundary']:c['testedSourceDigest']=digest(initial)
 elif c['label']=='independent-boundary-2':c['testedSourceDigest']=digest(fresh)
save('state.json',s)
cleanup_cmd=['lsof','-nP','+D',str(S)];p=subprocess.run(cleanup_cmd,capture_output=True);(O/'scratch-open-handles.log').write_bytes(p.stdout+p.stderr)
assert p.returncode==1 and not p.stdout, 'owned scratch still open'
shutil.rmtree(S)
cleanup={'openHandles':{'argv':cleanup_cmd,'exitCode':p.returncode,'output':'scratch-open-handles.log','outputSHA256':sha(O/'scratch-open-handles.log'),'observedOpenHandles':False},'ownedScratch':str(S),'ownedScratchRemoved':not S.exists(),'PostgreSQLCreated':False,'containersCreated':False,'nativeOrPhysicalInstancesCreated':False,'scope':'Only unique reviewer-owned source scratch removed. Other projects and live sources preserved.'};save('cleanup.json',cleanup)
save('reviewer-attempts.json',{'failedReviewerTests':[{'output':'independent-boundary.log','passed':3,'failed':1,'source':'review_endpoint_boundary_test-attempt1.exs','reason':'Reviewer expectation incorrectly rejected dot separating hostname labels; candidate accepted valid a.b.review.invalid. Corrected only test expectation; final four cases pass.'}],'failedInternalComparison':[{'command':'Inline python comparison h[inputs] == complete corrected-source manifest','exitCode':1,'observation':'Host collector has 62 consumed inputs; full candidate has 69 because seven protocol fixture/generator files are unused by hosted tests. Initial assertion was too broad.','resolution':'assess_evidence.py verifies all 62 host inputs/archive and all 974 Linux source/dependency entries exactly.'}],'productFindings':[]})
D=R/'docs/hosted-identity-startup-correction-review.md'
bindings={str(p.relative_to(O)):sha(p) for p in sorted(O.rglob('*')) if p.is_file() and p.name!='receipt.json'}
receipt={'schema':1,'status':'accepted-for-root-integration-development-slice','observedUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'reviewer':'hosted_identity_startup_correction_review','documentation':str(D.relative_to(R)),'documentationSHA256':sha(D),'correctionReceiptSHA256':v['packets']['hosted-identity-startup-correction']['receiptSHA256'],'acceptedHostedBase':v['hostedBase'],'reviewHead':v['reviewHead'],'correctedSourceDigest':v['correctedSourceDigest'],'cumulativePatchSHA256':'b8e19489a86e4bfe621dc478070f48c4aebad58dc98d950599020eecad0add49','correctionDeltaSHA256':'1b5fee53a73ddcafb3122c2bad874985a191a67c472b12210cd12b217b1439d1','producerBindingsVerified':92,'originalImplementationBindingsVerified':197,'originalReviewBindingsVerified':80,'candidateSourceFiles':69,'originalStartupOverlayFilesUnchanged':10,'dependencyFiles':914,'dependencyDigest':v['dependencyDigest'],'reviewSourceDigest':digest(fresh),'sourceArchiveSHA256':sha(O/'review-source.tar.gz'),'freshTests':{'oldIndependentAdversarial':{'passed':9,'failed':0},'oldMinimalRegressions':{'passed':4,'failed':0},'correctionFocused':{'passed':14,'failed':0},'newIndependentBoundaries':{'passed':4,'failed':0},'totalPassed':31,'platform':'macOS arm64; Elixir 1.20.4; OTP 29'},'reusedEvidence':{'earlierIndependentNormal':'macOS 85 passed + two Linux-only skips; Linux 87 passed; actual Application/Endpoint/PostgreSQL lifecycle and production DNS/HTTPS adapter','correctedProducerNormal':'macOS 93 passed + two Linux-only skips; Linux 95 passed; source/output/archive/metrics/cleanup independently verified','correctedProducerRelease':'build pass; expected missing-config exit 1; four test-only exports excluded','freshIndependentLifecycleOrNetworkReplay':False,'reason':'Exact unchanged startup/transport/owner source and dependencies; no unresolved new concern. Fresh focused independent replay covers both changed anchors.'},'findingDisposition':{'IR-F01':'resolved on exact corrected candidate; no malformed endpoint transport exploit claimed'},'unresolvedFindings':[],'recommendation':'Root may integrate the exact cumulative patch as a development slice. No GA acceptance or production authorization.','failedAttempts':'reviewer-attempts.json; initial reviewer source and output retained. Historical product finding/baseline failures remain in frozen prior packets.','limitations':['Normal corrected full matrix/release are verified producer receipts, not fresh independent executions in this review.','Synthetic loopback PostgreSQL without TLS; production DB TLS configuration only.','Synthetic CA/DNS/TLS/signed tokens; no real identity provider.','No authenticated HTTP, membership, permissions, provider selection/discovery, durable registry, Neon/Cloudflare operation, separately published FieldLog, native/physical, customer or GA qualification.','Physical phones disconnected and deferred; no UI work.','No live product/tracker/frozen packet changes, commit/push, production publication or credentials.'],'cleanup':cleanup,'additionalCommand':{'argv':['python3',str(O/'assess_evidence.py')],'cwd':str(R),'exitCode':0,'output':'evidence-assessment.log','outputSHA256':sha(O/'evidence-assessment.log')},'bindings':bindings}
save('receipt.json',receipt);print(json.dumps({'receiptSHA256':sha(O/'receipt.json'),'reviewSourceDigest':digest(fresh),'boundReviewFiles':len(bindings),'freshPassed':31,'unresolvedFindings':0,'scratchRemoved':not S.exists()}))
